package com.hbm.satellite.control;
import java.util.List;import net.minecraft.core.registries.Registries;import net.minecraft.world.flag.FeatureFlags;import net.minecraft.world.inventory.MenuType;import net.minecraft.world.item.*;import net.minecraft.world.level.block.entity.BlockEntityType;import net.neoforged.bus.api.IEventBus;import net.neoforged.neoforge.network.IContainerFactory;import net.neoforged.neoforge.registries.*;import net.neoforged.neoforge.capabilities.*;import net.neoforged.neoforge.items.wrapper.*;
public final class SatelliteControlContent {
 private static final DeferredRegister.Blocks BLOCKS=DeferredRegister.createBlocks("hbm");private static final DeferredRegister.Items ITEMS=DeferredRegister.createItems("hbm");private static final DeferredRegister<BlockEntityType<?>> ENTITIES=DeferredRegister.create(Registries.BLOCK_ENTITY_TYPE,"hbm");private static final DeferredRegister<MenuType<?>> MENUS=DeferredRegister.create(Registries.MENU,"hbm");
 public static final DeferredBlock<SatelliteLinkerBlock> BLOCK=BLOCKS.register("machine_satlinker",SatelliteLinkerBlock::new);public static final DeferredItem<BlockItem> ITEM=ITEMS.registerSimpleBlockItem("machine_satlinker",BLOCK);public static final DeferredItem<SatelliteCoordinateItem> COORDINATE=ITEMS.register("sat_coord",SatelliteCoordinateItem::new);public static final DeferredItem<SatelliteDesignatorItem> DESIGNATOR=ITEMS.register("sat_designator",SatelliteDesignatorItem::new);
 public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<SatelliteLinkerBlockEntity>> ENTITY=ENTITIES.register("sat_linker",()->BlockEntityType.Builder.of(SatelliteLinkerBlockEntity::new,BLOCK.get()).build(null));public static final DeferredHolder<MenuType<?>,MenuType<SatelliteLinkerMenu>> MENU=MENUS.register("sat_linker",()->new MenuType<>((IContainerFactory<SatelliteLinkerMenu>)SatelliteLinkerMenu::new,FeatureFlags.DEFAULT_FLAGS));
 public static void register(IEventBus bus){BLOCKS.register(bus);ITEMS.register(bus);ENTITIES.register(bus);MENUS.register(bus);bus.addListener(SatelliteCoordinateControl::register);bus.addListener(SatelliteControlContent::capabilities);}private static void capabilities(RegisterCapabilitiesEvent event){event.registerBlockEntity(Capabilities.ItemHandler.BLOCK,ENTITY.get(),(linker,side)->side==null?new InvWrapper(linker):new SidedInvWrapper(linker,side));}public static List<ItemStack> creativeStacks(String tab){return tab.equals("missile")?List.of(new ItemStack(ITEM.get()),new ItemStack(COORDINATE.get()),new ItemStack(DESIGNATOR.get())):List.of();}private SatelliteControlContent(){}
}
